create or replace function public.spike_battle_create(p_opponent_id uuid,p_title text,p_description text default '',p_post_id text default null,p_duration_hours integer default 48) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare uid uuid:=auth.uid(); bid uuid; begin if uid is null then raise exception 'Authentication required'; end if; if p_opponent_id is null or p_opponent_id=uid then raise exception 'Choose another person'; end if; if not exists(select 1 from public.friendships f where(f.user_id=uid and f.friend_id=p_opponent_id)or(f.user_id=p_opponent_id and f.friend_id=uid)) then raise exception 'Battles are available between friends'; end if; insert into public.spike_battles(creator_id,opponent_id,post_id,title,description,ends_at) values(uid,p_opponent_id,nullif(trim(p_post_id),''),trim(p_title),coalesce(trim(p_description),''),now()+make_interval(hours=>least(greatest(coalesce(p_duration_hours,48),1),168))) returning id into bid; perform public.spike_season_award_points(uid,15,'battle_created'); insert into public.notifications(user_id,type,data,priority,event_key,group_key) values(p_opponent_id,'spike_battle_invite',jsonb_build_object('battle_id',bid,'title',trim(p_title),'from_user_id',uid),'high','spike_battle_invite:'||bid::text,'spike_battle:'||bid::text); return jsonb_build_object('ok',true,'battle_id',bid); end $$;
create or replace function public.spike_chain_create(p_title text,p_description text default '',p_root_post_id text default null,p_first_entry text default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare uid uuid:=auth.uid(); cid uuid; eid uuid; begin if uid is null then raise exception 'Authentication required'; end if; insert into public.spike_signal_chains(creator_id,root_post_id,title,description) values(uid,nullif(trim(p_root_post_id),''),trim(p_title),coalesce(trim(p_description),'')) returning id into cid; if nullif(trim(p_first_entry),'') is not null then insert into public.spike_signal_chain_entries(chain_id,user_id,content) values(cid,uid,trim(p_first_entry)) returning id into eid; perform public.spike_season_award_points(uid,4,'chain_entry'); else perform public.spike_season_award_points(uid,10,'chain_created'); end if; return jsonb_build_object('ok',true,'chain_id',cid,'entry_id',eid); end $$;
create or replace function public.spike_chain_add_entry(p_chain_id uuid,p_parent_entry_id uuid,p_content text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare uid uuid:=auth.uid(); eid uuid; begin if uid is null then raise exception 'Authentication required'; end if; if not exists(select 1 from public.spike_signal_chains where id=p_chain_id) then raise exception 'Chain not found'; end if; if p_parent_entry_id is not null and not exists(select 1 from public.spike_signal_chain_entries where id=p_parent_entry_id and chain_id=p_chain_id) then raise exception 'Parent entry not found'; end if; insert into public.spike_signal_chain_entries(chain_id,parent_entry_id,user_id,content) values(p_chain_id,p_parent_entry_id,uid,trim(p_content)) returning id into eid; perform public.spike_season_award_points(uid,4,'chain_entry'); return jsonb_build_object('ok',true,'entry_id',eid); end $$;
create or replace function public.spike_mission_create(p_title text,p_description text,p_target integer,p_xp_reward integer default 100,p_days integer default 7) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare uid uuid:=auth.uid(); mid uuid; begin if uid is null then raise exception 'Authentication required'; end if; insert into public.spike_community_missions(creator_id,title,description,target,xp_reward,ends_at) values(uid,trim(p_title),coalesce(trim(p_description),''),least(greatest(p_target,1),100000),least(greatest(coalesce(p_xp_reward,100),0),10000),now()+make_interval(days=>least(greatest(coalesce(p_days,7),1),30))) returning id into mid; insert into public.spike_community_mission_members(mission_id,user_id) values(mid,uid); perform public.spike_season_award_points(uid,10,'mission_created'); return jsonb_build_object('ok',true,'mission_id',mid); end $$;
create or replace function public.spike_mission_join(p_mission_id uuid) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare uid uuid:=auth.uid(); cap int; n int; already boolean; begin if uid is null then raise exception 'Authentication required'; end if; select max_participants into cap from public.spike_community_missions where id=p_mission_id and active and ends_at>now(); if cap is null then raise exception 'Mission not available'; end if; already:=exists(select 1 from public.spike_community_mission_members where mission_id=p_mission_id and user_id=uid); select count(*) into n from public.spike_community_mission_members where mission_id=p_mission_id; if n>=cap and not already then raise exception 'Mission is full'; end if; insert into public.spike_community_mission_members(mission_id,user_id) values(p_mission_id,uid) on conflict do nothing; if not already then perform public.spike_season_award_points(uid,5,'mission_join'); end if; return jsonb_build_object('ok',true); end $$;
create or replace function public.spike_mission_progress(p_mission_id uuid,p_increment integer default 1) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare uid uuid:=auth.uid(); target int; xp int; oldp int; newp int; completed boolean:=false; inc int; begin if uid is null then raise exception 'Authentication required'; end if; select m.target,m.xp_reward into target,xp from public.spike_community_missions m join public.spike_community_mission_members mm on mm.mission_id=m.id and mm.user_id=uid where m.id=p_mission_id and m.active and m.ends_at>now(); if target is null then raise exception 'Join an active mission first'; end if; select progress into oldp from public.spike_community_mission_members where mission_id=p_mission_id and user_id=uid for update; inc:=least(greatest(coalesce(p_increment,1),1),10); newp:=least(target,oldp+inc); completed:=newp>=target and oldp<target; update public.spike_community_mission_members set progress=newp,completed_at=case when completed then now() else completed_at end where mission_id=p_mission_id and user_id=uid; perform public.spike_season_award_points(uid,least(inc,3),'mission_join'); if completed then perform public.spike_gamification_award(uid,xp,'community_mission',p_mission_id::text,'{}'::jsonb); perform public.spike_season_award_points(uid,25,'mission_complete'); end if; return jsonb_build_object('ok',true,'progress',newp,'target',target,'completed',completed,'xp_awarded',case when completed then xp else 0 end); end $$;
create or replace function public.spike_circle_create(p_name text,p_description text default '',p_privacy text default 'private') returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare uid uuid:=auth.uid(); cid uuid; begin if uid is null then raise exception 'Authentication required'; end if; if p_privacy not in('private','discoverable') then raise exception 'Invalid privacy'; end if; insert into public.spike_circles(owner_id,name,description,privacy) values(uid,trim(p_name),coalesce(trim(p_description),''),p_privacy) returning id into cid; insert into public.spike_circle_members(circle_id,user_id,role) values(cid,uid,'owner'); perform public.spike_season_award_points(uid,10,'circle_created'); return jsonb_build_object('ok',true,'circle_id',cid); end $$;
create or replace function public.spike_circle_join(p_circle_id uuid) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare uid uuid:=auth.uid(); priv text; already boolean; begin if uid is null then raise exception 'Authentication required'; end if; select privacy into priv from public.spike_circles where id=p_circle_id; if priv is null then raise exception 'Circle not found'; end if; if priv<>'discoverable' then raise exception 'This Circle is private. Ask the owner to invite you.'; end if; already:=exists(select 1 from public.spike_circle_members where circle_id=p_circle_id and user_id=uid); insert into public.spike_circle_members(circle_id,user_id) values(p_circle_id,uid) on conflict do nothing; if not already then perform public.spike_season_award_points(uid,5,'circle_join'); end if; return jsonb_build_object('ok',true); end $$;
create or replace function public.spike_circle_send_message(p_circle_id uuid,p_content text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare uid uuid:=auth.uid(); mid uuid; begin if uid is null then raise exception 'Authentication required'; end if; if not exists(select 1 from public.spike_circle_members where circle_id=p_circle_id and user_id=uid) then raise exception 'Join the Circle first'; end if; insert into public.spike_circle_messages(circle_id,user_id,content) values(p_circle_id,uid,trim(p_content)) returning id into mid; perform public.spike_season_award_points(uid,2,'circle_message'); return jsonb_build_object('ok',true,'message_id',mid); end $$;
create or replace function public.spike_battle_vote(p_battle_id uuid,p_choice_user_id uuid) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare uid uuid:=auth.uid(); b public.spike_battles; cv int; ov int; winner uuid; had_vote boolean; begin if uid is null then raise exception 'Authentication required'; end if; select * into b from public.spike_battles where id=p_battle_id for update; if not found then raise exception 'Battle not found'; end if; if b.status<>'open' or b.ends_at<=now() then raise exception 'This battle is closed'; end if; if p_choice_user_id not in(b.creator_id,b.opponent_id) then raise exception 'Invalid battle choice'; end if; if uid in(b.creator_id,b.opponent_id) then raise exception 'Participants cannot vote in their own battle'; end if; had_vote:=exists(select 1 from public.spike_battle_votes where battle_id=b.id and voter_id=uid); insert into public.spike_battle_votes(battle_id,voter_id,choice_user_id) values(b.id,uid,p_choice_user_id) on conflict(battle_id,voter_id) do update set choice_user_id=excluded.choice_user_id,created_at=now(); if not had_vote then perform public.spike_season_award_points(uid,3,'battle_vote'); end if; select count(*) into cv from public.spike_battle_votes where battle_id=b.id and choice_user_id=b.creator_id; select count(*) into ov from public.spike_battle_votes where battle_id=b.id and choice_user_id=b.opponent_id; if cv+ov>=50 and abs(cv-ov)>=10 then winner:=case when cv>ov then b.creator_id else b.opponent_id end; end if; if winner is not null then update public.spike_battles set status='closed',winner_id=winner,closed_at=now() where id=b.id; insert into public.notifications(user_id,type,data,priority,event_key,group_key) select u,'spike_battle_result',jsonb_build_object('battle_id',b.id,'winner_id',winner),'high','spike_battle_result:'||b.id::text||':'||u::text,'spike_battle:'||b.id::text from unnest(array[b.creator_id,b.opponent_id]) u; end if; return jsonb_build_object('ok',true,'creator_votes',cv,'opponent_votes',ov,'status',case when winner is null then 'open' else 'closed' end,'winner_id',winner); end $$;
